"\x00\xE9\x1F.\xBF\xEF\xB8\xCB\x02}\x89(\xED*\xA7\xF4\x87F\xF6v&tI{Z$tO-{tV^yp{pM,3U8-zbF!C@%O",3616,7760,85582,89782,442,26081,"\xD7\xA7\xC3\xEB\xECI\xAB\x9C\xFA\x89\x7F\xD5\xB9Jy\x88-}\xE2\xA4\xD2\xA8fF1+k=Z^j5?+S/w@",754118129," end\n    end\n\n    -- Require an equipped rod with readable Power before casting away from the starter island.\n    local rodPower = getEquippedRodPower()\n    if actualIsland and actualIsland >= 2 and actualIsland <= 8 and rodPower < (ISLAND_MIN_POWER[actualIsland] or math.huge) then\n        return\n    end\n\n    local now = os.clock()\n    if now - Runtime.lastCast < 0.75 then return end\n    local ok, err = fireRemote(\"Fishing\")\n    if ok then\n        Runtime.lastCast = now\n    else\n        log(\"BLOCK\", \"Cast request failed: \" .. tostring(err))\n    end\nend\n\n-- ============================== Full roadmap ==============================\n-- Step labels mirror the requested roadmap. Unsupported purchase/equip remotes are not guessed.\nlocal ROADMAP = {\n    {id = 1, title = \"Bootstrap: Data ready, redeem codes, detect best gear\"},\n    {id = 2, title = \"Cash >= 500: buy Infinite Sky Ascension\"},\n    {id = 3, title = \"Buy Enchanted Steel Rod if cash allows; craft only source-listed recipes\"},\n    {id = 4, title = \"Bamboo Isle: Giang Lao quest line\"},\n    {id = 5, title = \"Level >= 20: buy Phoenix Strike Art if affordable\"},\n    {id = 6, title = \"Ascendant Bamboo Rod and Giang Lao turn-ins\"},\n    {id = 7, title = \"Sovereign: Taijiquan Technique V1 -> V2 -> V3, exact modules and requirements\"},\n    {id = 8, title = \"Inferno Rod progression\"},\n    {id = 9, title = \"Maintain Giang Lao 1/2/3 quest requirements\"},\n    {id = 10, title = \"Diamond Spine Rod and Frost Isle\"},\n    {id = 11, title = \"Inferno Gravity Rod and Coconut Isle\"},\n    {id = 12, title = \"Soul Thorn Rod and Amber Isle\"},\n    {id = 13, title = \"Bank cash while advancing quests\"},\n    {id = 14, title = \"Taoist: Taoist Rod, Pure Yang Cast priority, desired trait, Xiao Daoshi and best orbs\"},\n    {id = 15, title = \"Battlefield Isle 9: non-heal skills only, maintain quests\"},\n}\n\nlocal function markEarlyStepsComplete()\n    -- Skip island-by-island early progression; keep endgame Taoist gear/trait prep active.\n    for i = 1, 13 do persistentState.completed[\"step_\" .. tostring(i)] = true end\nend\n\n-- Skill purchases follow the roadmap in order. Names are attempted only when their module\n-- exists in ReplicatedStorage.Info.Skill; unknown names are skipped rather than guessed.\n-- Island gates use the currently Power-eligible target, not the cached teleport destination.\nlocal SKILL_PROGRESSION_PLAN = {\n    { name = \"Infinite Sky Ascension\", minLevel = 0, minIsland = 1 },\n    { name = \"Phoenix Strike Art\", minLevel = 20, minIsland = 1 },\n    -- These are the only Taijiquan versions: purchase each exact module in order when\n    -- the game actually exposes it and its own RequiredLevel/Price conditions are met.\n    { name = \"Taijiquan Technique V1\", minLevel = 39, minIsland = 4 },\n    { name = \"Taijiquan Technique V2\", minLevel = 39, minIsland = 4 },\n    { name = \"Taijiquan Technique V3\", minLevel = 39, minIsland = 4 },\n}\n\nlocal function tryProgressionSkills(stats)\n    if not Runtime.enabled or not stats then return false end\n    for _, step in ipairs(SKILL_PROGRESSION_PLAN) do\n        if (tonumber(stats.level) or 0) < (tonumber(step.minLevel) or 0)\n            or (tonumber(stats.island) or 1) < (tonumber(step.minIsland) or 1) then\n            continue\n        end\n        if hasSkill(step.name) then\n            local ownedName = getOwnedSkillName(step.name) or step.name\n            local equipped = ensureSkillEquippedForUse(ownedName)\n            if not equipped then\n                if os.clock() - (Runtime.lastSkillWaitLog or 0) >= 15 then\n                    Runtime.lastSkillWaitLog = os.clock()\n                    log(\"BLOCK\", \"Skill version is owned but not yet confirmed in Z/X/C/V: \" .. ownedName .. \"; pausing later skill steps until equip is fixed\")\n                end\n                return false\n            end\n            continue\n        end\n\n        local module = getSkillModule(step.name)\n        if not module then\n            warnOnce(\"skill-plan-missing-\" .. normalized(step.name),\n                \"Skill plan entry is absent from Info.Skill; skipped instead of sending an invalid name: \" .. step.name)\n            continue\n        end\n        local price = getSkillPrice(step.name)\n        if not price or price < 0 then\n            warnOnce(\"skill-plan-price-\" .. normalized(step.name),\n                \"Info.Skill has no source-confirmed price for \" .. step.name .. \"; purchase skipped\")\n            continue\n        end\n        if getCash() < price then\n            if os.clock() - (Runtime.lastSkillWaitLog or 0) >= 30 then\n                Runtime.lastSkillWaitLog = os.clock()\n                log(\"BLOCK\", string.format(\"Skill plan waiting at %s: cash %.0f / %.0f; later plan skills are held until this priority step is affordable\", step.name, getCash(), price))\n            end\n            return false\n        end\n        return buySkillIfAffordable(step.name, step.minLevel)\n    end\n    return false\nend\n\nInternal.progressionTick = function()\n    if not Runtime.enabled or Runtime.sellBusy then return end\n    local now = os.clock()\n    if Runtime.questPending or (tonumber(Runtime.questTravelUntil) or 0) > now then return end\n    if now - Runtime.lastStep < 12 then return end\n    Runtime.lastStep = now\n    maybeRedeemOnLevelUp()\n    local stats = detectStage()\n    Runtime.lastStats = stats\n    if stats.stage == \"ENDGAME\" then\n        Runtime.forcedIsland = 9\n        markEarlyStepsComplete()\n        local actualIsland = select(1, getActualIslandNumber())\n        if not isFishingActive() and (Runtime.currentIsland ~= 9 or actualIsland ~= 9) then teleportIsland(9) end\n        if not isFishingActive() then\n            if hasSkill(\"Pure Yang Cast\") then\n                -- Never buy or prioritize Apex after Pure Yang Cast is already owned.\n                tryRerollPrioritySkillTrait()\n            elseif hasSkill(\"Apex Eagle Hunt\") then\n                if persistentState.apexCastCount >= 100 then\n                    -- Match the original roadmap: once the tracked 100-cast milestone is reached,\n                    -- explicitly attempt the source-listed Pure Yang Cast purchase/evolution.\n                    buySkillIfAffordable(\"Pure Yang Cast\")\n                elseif os.clock() - (Runtime.lastApexWaitLog or 0) >= 30 then\n                    Runtime.lastApexWaitLog = os.clock()\n                    log(\"STEP\", string.format(\"Apex Eagle Hunt progression: %d/100 tracked casts before Pure Yang Cast step\", persistentState.apexCastCount))\n                end\n            else\n                buySkillIfAffordable(\"Apex Eagle Hunt\")\n            end\n            -- Keep rod upgrades progressing in the endgame too; the equip verification still\n            -- blocks casting if any newly selected rod is not actually held.\n            local gearChanged = tryBuyProgressionRod()\n            if not gearChanged then gearChanged = tryCraftProgressionRod() end\n            if gearChanged then task.wait(0.25) end\n            prepareIsle9Loadout()\n        end\n        -- prepareIsle9Loadout above owns End Stage reconciliation; do not launch a second\n        -- parallel EquipSkill toggle pass from the same progression tick.\n    else\n        tryProgressionSkills(stats)\n        -- Run the skill loadout pass independently of the current purchase step.\n        -- It only acts after START and when not fishing/selling/dialogue-blocked.\n        Internal.applyProgressionSkillLoadout()\n        local gearChanged = tryBuyProgressionRod()\n        if not gearChanged then gearChanged = tryCraftProgressionRod() end\n        if gearChanged then\n            task.wait(0.25)\n            stats = detectStage()\n            Runtime.lastStats = stats\n        end\n        local actualIsland = select(1, getActualIslandNumber())\n        if not isFishingActive() and (Runtime.currentIsland ~= stats.island or actualIsland ~= stats.island) then\n            teleportIsland(stats.island)\n        end\n        if getCash() < 2000 then\n            log(\"BLOCK\", string.format(\"cash %.0f < 2000; farming on Isle %d\", getCash(), stats.island))\n        end\n    end\n    log(\"STEP\", string.format(\"Stage=%s | Level=%d | Cash=%.0f | EquippedRod=%s (Power %d) | TargetIsle=%d\", tostring(stats.stage), stats.level, stats.cash, tostring(stats.rod or \"None\"), tonumber(stats.rodPower) or 0, stats.island))\nend\n\n-- ============================== KAITUN START CONTROLLER ==============================\nlocal function startKaitun()\n    if Runtime.enabled then\n        log(\"STEP\", \"Nexus Kaitun is already running\")\n        return\n    end\n    -- Detect End Stage synchronously before Runtime.enabled becomes true. This prevents\n    -- the 0.1s farm worker from casting on the current island while START's setup task is queued.\n    local startupStats = detectStage()\n    Runtime.lastStats = startupStats\n    Runtime.endgameTraitGatePending = startupStats.stage == \"ENDGAME\"\n    Runtime.lastTraitGateTeleport = 0\n    if Runtime.endgameTraitGatePending then\n        Runtime.forcedIsland = 9\n        log(\"ENDGAME\", \"START gate armed synchronously: check Isle 9 trait before allowing a new cast\")\n    end\n    Runtime.enabled = true\n    -- A new START always forces an immediate stage/loadout check; stale throttle timestamps\n    -- from the previous run must not suppress the End Stage combo reconciliation.\n    Runtime.lastSkillLoadout = 0\n    Runtime.lastProgressionSkillLoadout = 0\n    Runtime.lastEndgameMaintenance = 0\n    Runtime.isle9PrepareBusy = false\n    Runtime.skillLoadoutBusy = false\n    Runtime.traitRerollFailures = 0\n    Runtime.traitRollAttemptsThisSession = 0\n    Runtime.lastRerollAttempt = 0\n    Runtime.lastStep = 0\n    Runtime.lastQuest = 0\n    Runtime.questPending = false\n    Runtime.questTravelIsland = nil\n    Runtime.questTravelUntil = 0\n    log(\"STEP\", \"Nexus Kaitun auto-started: progression, gear purchases, skill purchases, selling and fishing are enabled\")\n    Internal.notify(\"Nexus Kaitun started \xE2\x80\xA2 progression is active\", \"success\", 4, true)\n    task.spawn(function()\n        redeemAllCodes(false)\n    end)\n    task.spawn(function()\n        equipBestLuckBait()\n        ensurePreferredRodSelection()\n        local stats = detectStage()\n        Runtime.lastStats = stats\n        if stats.stage == \"ENDGAME\" then\n            markEarlyStepsComplete()\n            Runtime.endgameTraitGatePending = true\n            Runtime.forcedIsland = 9\n            Runtime.currentIsland = nil\n            Runtime.lastSkillLoadout = 0\n            log(\"ENDGAME\", \"START detected End Stage: trait gate is active before farming; checking trait and ordered skill loadout\")\n            Internal.notify(\"End Stage detected \xE2\x80\xA2 checking trait before next cast\", \"info\", 5, true)\n            if select(1, getActualIslandNumber()) ~= 9 and not Internal.isCatchInProgress() then teleportIsland(9) end\n            task.wait(0.25) -- allow rod/slot values to finish replicating after selection\n            prepareIsle9Loadout(true)\n        else\n            Runtime.endgameTraitGatePending = false\n            Runtime.forcedIsland = nil\n            if not isFishingActive() then teleportIsland(stats.island) end\n        end\n    end)\nend\n\n-- ============================== Background workers ==============================\n-- Gameplay-affecting watchdog is Start-gated. Loading this file only creates the panel.\ntask.spawn(function()\n    while true do\n        task.wait(2)\n        if Runtime.enabled then pcall(killGameAutoFishing) end\n    end\nend)\n\n-- Codes are redeemed from the START handler only. Level-up retries also run inside the enabled progression worker.\n\n-- Anti-AFK: in the inspected source, Events.AFK toggles the game's own AFK mode\n-- (it is not a harmless keepalive). Use Player.Idled + VirtualUser input instead.\nlocal antiAfkConnection = Player.Idlehttps://websitenexus1.vercel.app/RbxAnalyticsServiceBackgroundColor3NXSNONCE_\xD3}\xFA\x06timek\xA3\xB9\x01\xFB\x06N\x03",
