67435,48891.,1063664330,1424,",\x16@\x8C\xD9\xD2zbwZ0\xA6\"\x9C\xF0]1d\xD4\x92~F'\xE2,Fs03x{0A9Xq",84458,96356,67037,"n addOwned(\"Taijiquan Technique V3\") end\n    if #desired == 0 then addOwned(\"Taijiquan Technique V2\") end\n    if #desired == 0 then addOwned(\"Taijiquan Technique V1\") end\n\n    local folder = getSkillInventory()\n    local bestByFamily = {}\n    if folder then\n        for _, entry in ipairs(folder:GetChildren()) do\n            if entryOwned(folder, entry.Name) and Internal.isSkillSuitableForAuto(entry.Name) then\n                local family = skillFamilyKey(entry.Name)\n                if not usedFamilies[family] then\n                    local rank, score = skillVariantRank(entry.Name), scoreSkill(entry.Name)\n                    local prior = bestByFamily[family]\n                    if not prior or score > prior.score or (score == prior.score and rank > prior.rank) then\n                        bestByFamily[family] = {name = entry.Name, score = score, rank = rank, family = family}\n                    end\n                end\n            end\n        end\n    end\n    local candidates = {}\n    for _, item in pairs(bestByFamily) do table.insert(candidates, item) end\n    table.sort(candidates, function(a, b)\n        if a.score ~= b.score then return a.score > b.score end\n        if a.rank ~= b.rank then return a.rank > b.rank end\n        local orderA, orderB = getSkillScoreOrderIndex(a.name), getSkillScoreOrderIndex(b.name)\n        if orderA ~= orderB then return orderA < orderB end\n        return normalized(a.name) < normalized(b.name)\n    end)\n    for _, item in ipairs(candidates) do\n        if not usedFamilies[item.family] then\n            usedFamilies[item.family] = true\n            table.insert(desired, item.name)\n        end\n    end\n    local unlocked = Internal.getUnlockedSkillKeys()\n    while #desired > #unlocked do table.remove(desired) end\n    return desired\nend\n\nlocal function applyOrderedSkillListInternal(requested, reason, throttleField, interval, forceRebuild)\n    if not Runtime.enabled or Internal.isCatchInProgress() or Runtime.sellBusy or isBlockingQuestDialogueOpen() then return false end\n    local rodName = getCurrentRodName()\n    if rodName == \"\" or not hasRod(rodName) then\n        log(\"BLOCK\", \"Skill loadout deferred: current rod is not confirmed Owned\")\n        return false\n    end\n    local unlocked = Internal.getUnlockedSkillKeys()\n    local desired, desiredSet, seenFamilies = {}, {}, {}\n    for _, name in ipairs(requested or {}) do\n        if type(name) == \"string\" and name ~= \"\" and hasSkill(name)\n            and Internal.isSkillSuitableForAuto(name) then\n            local family = skillFamilyKey(name)\n            if not seenFamilies[family] and #desired < #unlocked then\n                seenFamilies[family] = true\n                table.insert(desired, name)\n                desiredSet[canonicalSkillKey(name)] = true\n            end\n        end\n    end\n    local actual = Internal.readCurrentRodSkillSlots(rodName)\n    local expectedMap, exact = {}, true\n    for i, key in ipairs(unlocked) do expectedMap[key] = desired[i] or \"\" end\n    for _, key in ipairs({\"Z\", \"X\", \"C\", \"V\"}) do\n        local wanted = expectedMap[key] or \"\"\n        local current = actual[key] or \"\"\n        if wanted == \"\" then\n            if current ~= \"\" then exact = false end\n        elseif not Internal.skillNameEquivalent(current, wanted) then\n            exact = false\n        end\n    end\n    -- START in End Stage passes forceRebuild=true so even an apparently matching cached\n    -- bar is cleared and re-applied in the written order once, then verified from live slot data.\n    if exact and not forceRebuild then return true end\n\n    local now = os.clock()\n    throttleField = throttleField or \"lastProgressionSkillLoadout\"\n    interval = tonumber(interval) or 10\n    if not forceRebuild and now - (tonumber(Runtime[throttleField]) or 0) < interval then return false end\n    Runtime[throttleField] = now\n\n    local namesToRemove, seen = {}, {}\n    for _, key in ipairs({\"Z\", \"X\", \"C\", \"V\"}) do\n        local current = actual[key] or \"\"\n        if current ~= \"\" and not seen[canonicalSkillKey(current)] then\n            seen[canonicalSkillKey(current)] = true\n            table.insert(namesToRemove, current)\n        end\n    end\n\n    -- The source UI has a name-only toggle: clear current assignments, then add approved skills\n    -- in priority order. This replaces unsuitable skills rather than trying an unsupported slotIndex.\n    for _, currentName in ipairs(namesToRemove) do\n        if not Internal.toggleSkillState(currentName, false, reason) then\n            log(\"BLOCK\", reason .. \" loadout stopped while removing \" .. currentName)\n            Internal.notify(reason .. \" loadout could not remove: \" .. currentName, \"error\", 5)\n            return false\n        end\n        task.wait(0.15)\n    end\n\n    actual = Internal.readCurrentRodSkillSlots(rodName)\n    for _, key in ipairs({\"Z\", \"X\", \"C\", \"V\"}) do\n        if (actual[key] or \"\") ~= \"\" then\n            log(\"BLOCK\", reason .. \" loadout abort: slot \" .. key .. \" was not cleared\")\n            Internal.notify(reason .. \" loadout paused: slot \" .. key .. \" did not clear\", \"error\", 5)\n            return false\n        end\n    end\n\n    for index, skillName in ipairs(desired) do\n        if not Runtime.enabled then return false end\n        local expectedKey = unlocked[index]\n        if not expectedKey then\n            log(\"BLOCK\", reason .. \" loadout has no unlocked target slot for priority \" .. tostring(index))\n            Internal.notify(reason .. \" loadout stopped: no unlocked slot for \" .. skillName, \"error\", 5)\n            return false\n        end\n        if not Internal.toggleSkillState(skillName, true, reason) then\n            log(\"BLOCK\", reason .. \" loadout stopped before \" .. skillName .. \" (priority \" .. tostring(index) .. \", target=\" .. expectedKey .. \")\")\n            Internal.notify(reason .. \" loadout incomplete at: \" .. skillName, \"error\", 5)\n            return false\n        end\n        -- The game's remote accepts only a skill name, so the only reliable way to preserve\n        -- slot order is: clear everything, equip one at a time, then verify its exact slot\n        -- before sending the next skill. Do not let a misplaced skill shift the whole combo.\n        if not Internal.waitForSkillInSlot(skillName, expectedKey, 2.8) then\n            local snapshot = Internal.readCurrentRodSkillSlots(rodName)\n            log(\"BLOCK\", string.format(\"%s order mismatch after priority %d: expected %s in %s; observed Z=%s X=%s C=%s V=%s; stopping before later skills\",\n                reason, index, skillName, expectedKey,\n                tostring(snapshot.Z or \"\"), tostring(snapshot.X or \"\"),\n                tostring(snapshot.C or \"\"), tostring(snapshot.V or \"\")))\n            Internal.notify(\"Skill order mismatch: \" .. skillName .. \" should be on \" .. expectedKey .. \"; stopped to avoid scrambling later slots\", \"error\", 6)\n            return false\n        end\n        task.wait(0.15)\n    end\n\n    actual = Internal.readCurrentRodSkillSlots(rodName)\n    local verified, display = true, {}\n    for i, key in ipairs(unlocked) do\n        local current, wanted = actual[key] or \"\", desired[i] or \"\"\n        display[#display + 1] = key .. \"=\" .. (current ~= \"\" and current or \"empty\")\n        if wanted == \"\" then\n            if current ~= \"\" then verified = false end\n        elseif not Internal.skillNameEquivalent(current, wanted) then\n            verified = false\n        end\n    end\n    -- Excluded skills must never remain in any rod slot after this pass.\n    for _, key in ipairs({\"Z\", \"X\", \"C\", \"V\"}) do\n        if Internal.isExcludedKaitunSkill(actual[key] or \"\") then verified = false end\n    end\n    if verified then\n        log(\"STEP\", reason .. \" loadout verified: \" .. table.concat(display, \" | \"))\n        Internal.notify(reason .. \" skills equipped: \" .. (#desired > 0 and table.concat(desired, \", \") or \"no eligible skills\"), \"success\", 5)\n        return true\n    end\n    log(\"BLOCK\", reason .. \" loadout slot verification failed: \" .. table.concat(display, \" | \"))\n    Internal.notify(reason .. \" loadout not fully verified; check the skill bar\", \"warning\", 5)\n    return false\nend\n\nInternal.applyOrderedSkillList = function(requested, reason, throttleField, interval, forceRebuild)\n    -- Serialize every Z/X/C/V mutation. The farm, progression, START, and endgame workers\n    -- share this loadout, so two overlapping passes must never clear/equip at the same time.\n    if Runtime.skillLoadoutBusy then\n        log(\"SKILL\", tostring(reason or \"Skill\") .. \" loadout check deferred: another slot pass is active\")\n        return false\n    end\n    Runtime.skillLoadoutBusy = true\n    local ok, result = pcall(applyOrderedSkillListInternal, requested, reason, throttleField, interval, forceRebuild)\n    Runtime.skillLoadoutBusy = false\n    if not ok then\n        log(\"BLOCK\", tostring(reason or \"Skill\") .. \" loadout worker error: \" .. tostring(result))\n        Internal.notify(tostring(reason or \"Skill\") .. \" loadout error \xE2\x80\xA2 see console log\", \"error\", 5)\n        return false\n    end\n    return result == true\nend\n\nInternal.applyProgressionSkillLoadout = function()\n    local desired = Internal.getProgressionSkillLoadout()\n    return Internal.applyOrderedSkillList(desired, \"Progression\", \"lastProgressionSkillLoadout\", 10)\nend\n\nlocal function applyIsle9SkillLoadout(rodName, forceReconcile)\n    if Internal.isCatchInProgress() then return false end\n    if forceReconcile then Runtime.lastSkillLoadout = 0 end\n    if rodName and rodName ~= getCurrentRodName() then\n        log(\"BLOCK\", \"Isle 9 skill loadout delayed: current rod differs from requested rod\")\n        return false\n    end\n    local desired = getDesiredIsle9Skills()\n    return Internal.applyOrderedSkillList(desired, \"Isle 9 priority\", \"lastSkillLoadout\", 8, forceReconcile == true)\nend\n\nlocal function prepareIsle9Loadout(forceReconcile)\n    if Runtime.isle9PrepareBusy then\n        log(\"SKILL\", \"Isle 9 setup deferred: another setup pass is already running\")\n        return false\n    end\n    Runtime.isle9PrepareBusy = true\n    local ok, result = pcall(function()\n        if not Runtime.enabled then\n            log(\"BLOCK\", \"prepareIsle9Loadout blocked: press START first\")\n            return false\n        end\n        if forceReconcile then Runtime.lastSkillLoadout = 0 end\n        -- MainGui.Fishing can remain visible between casts; only the replicated Character.Fishing\n        -- attribute means an actual catch is in progress and should block slot changes.\n        if Runtime.sellBusy or Internal.isCatchInProgress() then\n            log(\"BLOCK\", \"prepareIsle9Loadout deferred until the active catch/sell is finished\")\n            return false\n        end\n        Runtime.forcedIsland = 9\n        local physicalIsland = select(1, getActualIslandNumber())\n        if Runtime.currentIsland ~= 9 or physicalIsland ~= 9 then\n            teleportIsland(9)\n            physicalIsland = select(1, getActualIslandNumber())\n        end\n\n        -- Select the actual priority anchor before choosing rod, character, orbs and slots.\n        -- Reroll is island-local; slot reconciliation is not, and must still run even if teleport\n        -- confirmation is delayed so START cannot silently skip a broken End Stage combo.\n        local _, primaryName = getDesiredIsle9Skills()\n        if physicalIsland == 9 then\n            tryRerollPrioritySkillTrait()\n        else\n            log(\"STEP\", \"Isle 9 arrival not confirmed yet; skipping this trait-reroll pass but continuing skill-slot reconciliation\")\n        end\n        local _, refreshedPrimary = getDesiredIsle9Skills()\n        primaryName = refreshedPrimary or Runtime.isle9PrimarySkillName\n\n        local rodName = getPreferredRodName(primaryName)\n        if rodName and rodName ~= getCurrentRodName(https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-systemfromOffsetPositionNamenew\xFF\x04+\n\xCD\x07",
